50	uint32_t GetDataTypeSize(DataType dt) {
51	  uint32_t dilation = 1;
52	  if (dt == ge::DT_FLOAT)
53	    dilation = 4;  // DT_FLOAT: 4 bytes
54	  else if (dt == ge::DT_FLOAT16)
55	    dilation = 2;  // DT_FLOAT16: 2 bytes
56	  else if (dt == ge::DT_INT16)
57	    dilation = 2;  // DT_INT16: 2 bytes
58	  else if (dt == ge::DT_UINT16)
59	    dilation = 2;  // DT_UINT16: 2 bytes
60	  else if (dt == ge::DT_INT32)
61	    dilation = 4;  // DT_INT32: 4 bytes
62	  else if (dt == ge::DT_UINT32)
63	    dilation = 4;  // DT_UINT32: 4 bytes
64	  else if (dt == ge::DT_INT64)
65	    dilation = 8;  // DT_INT64: 8 bytes
66	  else if (dt == ge::DT_UINT64)
67	    dilation = 8;  // DT_UINT64: 8 bytes
68	  else if (dt == ge::DT_INT8)
69	    dilation = 1;
70	  return dilation;
71	}
