73	int32_t GenOnesData(vector<int64_t> shapes, Tensor &input_tensor, TensorDesc &input_tensor_desc, DataType data_type,
74	                    int value) {
75	  input_tensor_desc.SetRealDimCnt(shapes.size());
76	  size_t size = 1;
77	  for (uint32_t i = 0; i < shapes.size(); i++) {
78	    size *= shapes[i];
79	  }
80	  uint32_t data_len = size * GetDataTypeSize(data_type);
81	  std::vector<uint8_t> pData(data_len, static_cast<uint8_t>(value));
82	  input_tensor = Tensor(input_tensor_desc, pData.data(), data_len);
83	  return SUCCESS;
84	}
