202	static Status BuildReluGraph(Graph &graph, std::vector<ge::Tensor> &input) {
203	  vector<int64_t> placeholder_01_shape = {1, 3, 32, 32};
204	  auto placeholder_01 = op::Data("placeholder_01").set_attr_index(0);
205	  TensorDesc placeholder_01_desc = TensorDesc(ge::Shape(placeholder_01_shape), FORMAT_NHWC, DT_FLOAT16);
206	  placeholder_01_desc.SetPlacement(ge::kPlacementHost);
207	  placeholder_01_desc.SetFormat(FORMAT_NHWC);
208	  Tensor tensor_placeholder_01;
209	
210	  Status ret = GenOnesData(placeholder_01_shape, tensor_placeholder_01, placeholder_01_desc, DT_FLOAT16, 1);
211	  if (ret != SUCCESS) {
212	    printf("%s - ERROR - [XIR]: Generate input data failed\n", GetTime().c_str());
213	    return FAILED;
214	  }
215	
216	  placeholder_01.update_input_desc_x(placeholder_01_desc);
217	  placeholder_01.update_output_desc_y(placeholder_01_desc);
218	  input.push_back(tensor_placeholder_01);
219	  graph.AddOp(placeholder_01);
220	
221	  auto relu_01 = op::Relu("relu_01").set_input_x(placeholder_01, 0);
222	
223	  relu_01.SetAttr("pattern", "ElemWise");
224	  TensorDesc tensor_desc_relu_01_x = relu_01.GetInputDescByName("x");
225	  TensorDesc tensor_desc_relu_01_y = relu_01.GetOutputDescByName("y");
226	
227	  tensor_desc_relu_01_x.SetOriginFormat(FORMAT_NHWC);
228	  tensor_desc_relu_01_y.SetOriginFormat(FORMAT_NHWC);
229	
230	  tensor_desc_relu_01_x.SetFormat(FORMAT_NHWC);
231	  tensor_desc_relu_01_y.SetFormat(FORMAT_NHWC);
232	
233	  relu_01.UpdateInputDesc("x", tensor_desc_relu_01_x);
234	  relu_01.UpdateOutputDesc("y", tensor_desc_relu_01_y);
235	  graph.AddOp(relu_01);
236	  printf("%s - INFO - [XIR]: Add relu op into ir compute graph finished\n", GetTime().c_str());
237	
238	  std::vector<Operator> inputs{placeholder_01};
239	  std::vector<Operator> outputs{relu_01};
240	  graph.SetInputs(inputs).SetOutputs(outputs);
241	
242	  return SUCCESS;
243	}
