300	static Status PrepareInputTensors(const std::vector<ge::Tensor> &input, std::vector<gert::Tensor> &input_device,
301	                                  aclrtStream stream) {
302	  input_device.resize(input.size());
303	  for (size_t i = 0; i < input.size(); i++) {
304	    auto input_size = input[i].GetSize();
305	    auto input_desc = input[i].GetTensorDesc();
306	    gert::StorageShape storage_shape({4, 50, 50, 3}, {4, 50, 50, 3});
307	    auto input_format = input_desc.GetFormat();
308	    gert::StorageFormat storage_format(input_format, input_format, {});
309	    auto input_dtype = input_desc.GetDataType();
310	    const uint8_t *input_buffer = input[i].GetData();
311	    void *inputdevBuffer = nullptr;
312	    aclError aclRet = aclrtMalloc(&inputdevBuffer, input_size, ACL_MEM_MALLOC_NORMAL_ONLY);
313	    if (aclRet != ACL_ERROR_NONE) {
314	      printf("[ACL run log] - INFO - [XIR]: malloc input dev buffer fail\n");
315	      return FAILED;
316	    }
317	    aclRet = aclrtMemcpy(inputdevBuffer, input_size, input_buffer, input_size, ACL_MEMCPY_HOST_TO_DEVICE);
318	    if (aclRet != ACL_ERROR_NONE) {
319	      printf("[ACL run log] - INFO - [XIR]: acl memcpy input to dev failed\n");
320	      return FAILED;
321	    }
322	    printf("[ACL run log] - INFO - [XIR]: acl memcpy input host to device success\n");
323	    input_device[i] = {storage_shape, storage_format, gert::kOnDeviceHbm, input_dtype, inputdevBuffer};
324	  }
325	  return SUCCESS;
326	}
