328	static Status ExecuteGraphAndSaveOutput(ge::Session &sess, uint32_t graph_id, aclrtStream stream,
329	                                        const std::vector<ge::Tensor> &input, std::vector<gert::Tensor> &input_device,
330	                                        std::vector<gert::Tensor> &output) {
331	  std::map<AscendString, AscendString> load_graph_options = {};
332	  Status ret = GeSessionLoadGraph(sess, graph_id, load_graph_options, stream);
333	  if (ret != SUCCESS) {
334	    printf("[IR run log] - INFO - [XIR]: GeSessionLoadGraph failed\n");
335	    return FAILED;
336	  }
337	  printf("[IR run log] - INFO - [XIR]: GeSessionLoadGraph success\n");
338	
339	  ret = PrepareInputTensors(input, input_device, stream);
340	  if (ret != SUCCESS) {
341	    return FAILED;
342	  }
343	
344	  size_t output_size = 4 * 48 * 48 * 3;
345	  void *outputdevBuffer = nullptr;
346	  aclrtMalloc(&outputdevBuffer, output_size, ACL_MEM_MALLOC_NORMAL_ONLY);
347	  output.resize(1);
348	  output[0] = {{{4, 48, 48, 3}, {4, 48, 48, 3}}, {}, gert::kOnDeviceHbm, {}, outputdevBuffer};
349	
350	  printf("[IR run log] - INFO - [XIR]: Start to run ir compute graph the second time\n");
351	  ret = GeSessionExecuteGraphWithStreamAsync(sess, graph_id, stream, input_device, output);
352	  if (ret != SUCCESS) {
353	    printf("[IR run log] - INFO - [XIR]: GeSessionExecuteGraphWithStreamAsync failed\n");
354	    return FAILED;
355	  }
356	  printf("[IR run log] - INFO - [XIR]: GeSessionExecuteGraphWithStreamAsync success\n");
357	
358	  aclError aclRet = aclrtSynchronizeStream(stream);
359	  if (aclRet != ACL_ERROR_NONE) {
360	    printf("[ACL run log] - INFO - [XIR]: sync stream failed\n");
361	    return FAILED;
362	  }
363	  printf("[ACL run log] - INFO - [XIR]: stream sync success\n");
364	
365	  string output_file = "./tc_ge_irrun_open_api_0014/tc_ge_irrun_open_api_0014_npu_output_";
366	  for (size_t i = 0; i < output.size(); i++) {
367	    string output1_file = output_file + std::to_string(i) + ".bin";
368	    auto output1_addr = output[i].GetData<uint8_t>();
369	    auto output_size1 = output[i].GetSize();
370	    void *output1_hostBuffer = nullptr;
371	    aclRet = aclrtMallocHost(&output1_hostBuffer, output_size1);
372	    aclrtMemcpy(output1_hostBuffer, output_size1, output1_addr, output_size1, ACL_MEMCPY_DEVICE_TO_HOST);
373	    WriteDataToFile((const char *)output1_file.c_str(), output_size1, (uint8_t *)output1_hostBuffer);
374	    aclrtFreeHost(output1_hostBuffer);
375	  }
376	
377	  return SUCCESS;
378	}
