string GetTime() {
  time_t timep;
  time(&timep);
  char tmp[64];
  struct tm result;
  strftime(tmp, sizeof(tmp), "%Y-%m-%d %H:%M:%S,000", localtime_r(&timep, &result));
  return tmp;
}

uint32_t GetDataTypeSize(DataType dt) {
  uint32_t dilation = 1;
  if (dt == ge::DT_FLOAT)
    dilation = 4;  // DT_FLOAT: 4 bytes
  else if (dt == ge::DT_FLOAT16)
    dilation = 2;  // DT_FLOAT16: 2 bytes
  else if (dt == ge::DT_INT16)
    dilation = 2;  // DT_INT16: 2 bytes
  else if (dt == ge::DT_UINT16)
    dilation = 2;  // DT_UINT16: 2 bytes
  else if (dt == ge::DT_INT32)
    dilation = 4;  // DT_INT32: 4 bytes
  else if (dt == ge::DT_UINT32)
    dilation = 4;  // DT_UINT32: 4 bytes
  else if (dt == ge::DT_INT64)
    dilation = 8;  // DT_INT64: 8 bytes
  else if (dt == ge::DT_UINT64)
    dilation = 8;  // DT_UINT64: 8 bytes
  else if (dt == ge::DT_INT8)
    dilation = 1;
  return dilation;
}

int32_t GenOnesData(vector<int64_t> shapes, Tensor &input_tensor, TensorDesc &input_tensor_desc, DataType data_type,
                    int value) {
  input_tensor_desc.SetRealDimCnt(shapes.size());
  size_t size = 1;
  for (uint32_t i = 0; i < shapes.size(); i++) {
    size *= shapes[i];
  }
  uint32_t data_len = size * GetDataTypeSize(data_type);
  std::vector<uint8_t> pData(data_len, static_cast<uint8_t>(value));
  input_tensor = Tensor(input_tensor_desc, pData.data(), data_len);
  return SUCCESS;
}

int32_t WriteDataToFile(string bin_file, uint64_t data_size, uint8_t *inputData) {
  FILE *fp = fopen(bin_file.c_str(), "w");
  fwrite(inputData, sizeof(uint8_t), data_size, fp);
  fclose(fp);
  return SUCCESS;
}

int32_t LoadDataFromFile(string bin_file, vector<int64_t> shapes, Tensor &input_tensor, TensorDesc &input_tensor_desc,
                         DataType data_type) {
  size_t size = 1;
  for (uint32_t i = 0; i < shapes.size(); i++) {
    size *= shapes[i];
  }
  uint32_t data_size = size * GetDataTypeSize(data_type);
  FILE *fp = fopen(bin_file.c_str(), "r");
  uint32_t *memory = (uint32_t *)malloc(data_size * sizeof(uint32_t));
  fread(memory, sizeof(uint32_t), data_size, fp);
  fclose(fp);
  uint8_t *inputData = (uint8_t *)memory;
  input_tensor_desc.SetRealDimCnt(shapes.size());
  input_tensor = Tensor(input_tensor_desc, inputData, data_size);
  return SUCCESS;
}

